phase1.code:
// ---- Closures are anonymous functions that can capture variables ----

fn main() {
    // ---- Basic closure ----
    let add = |a, b| a + b;
    let result = add(5, 3);
    println!("add(5, 3) = {}", result);

    // ---- Closure with explicit types ----
    let multiply: fn(i32, i32) -> i32 = |a: i32, b: i32| a * b;
    println!("multiply(5, 3) = {}", multiply(5, 3));

    // ---- Closure capturing variables ----
    let factor = 3;
    let multiply_by = |x| x * factor;
    println!("multiply_by(5) = {}", multiply_by(5));

    // ---- Mutating captured variables ----
    let mut count = 0;
    let mut increment = || {
        count += 1;
        count
    };
    println!("increment() = {}", increment());
    println!("increment() = {}", increment());
    println!("increment() = {}", increment());

    // ---- Closures with move (take ownership) ----
    let name = String::from("Hero");
    let print_name = move || {
        println!("Name: {}", name);
    };
    print_name();
    // println!("{}", name);  // ERROR: name was moved

    // ---- Closures as arguments ----
    fn apply_twice(f: impl Fn(i32) -> i32, x: i32) -> i32 {
        f(f(x))
    }

    let double = |x| x * 2;
    let result = apply_twice(double, 5);
    println!("apply_twice(double, 5) = {}", result);

    // ---- Different closure traits ----
    // Fn: can be called multiple times, no mutation
    let add = |a, b| a + b;

    // FnMut: can be called multiple times, mutates captured variables
    let mut counter = 0;
    let mut increment = || {
        counter += 1;
        counter
    };

    // FnOnce: can be called once, takes ownership
    let name = String::from("Hero");
    let consume = || {
        drop(name);
        println!("Name consumed!");
    };
    consume();
    // consume();  // ERROR: called twice

    // ---- Using closures with iterators ----
    let numbers = vec![1, 2, 3, 4, 5];
    let doubled: Vec<i32> = numbers.iter().map(|x| x * 2).collect();
    println!("Doubled: {:?}", doubled);

    // ---- Closure that captures by reference ----
    let mut health = 100;
    let mut damage = || {
        health -= 10;
        health
    };
    println!("After damage: {}", damage());
    println!("After damage: {}", damage());
}

phase2.brokenCode:
fn main() {
    let name = String::from("Hero");
    let print_name = || {
        println!("Name: {}", name);
    };
    print_name();
    println!("{}", name);  // Works if borrowed, but might move if used differently
}

phase2.explanation:
Closures capture variables. If you move the variable into the closure, you can't use it after.

**The fix:**
```rust
let print_name = || {
    println!("Name: {}", name);  // Borrows, doesn't take ownership
};
```

**Rust-chan says:**
"Closures capture variables. Be aware of how they capture."
